# app/models/article.rb
class Article < ApplicationRecord
  # 1. Scope không tham số
  scope :published, -> { where(published: true) }
  scope :recent, -> { order(created_at: :desc) }

  # 2. Scope có tham số (An toàn khi tham số là nil)
  scope :by_category, ->(category_id) {
    where(category_id: category_id) if category_id.present?
  }

  # Ghép nối mượt mà không bao giờ sợ crash do nil:
  # Article.published.by_category(nil).recent.limit(10)
  # Nếu by_category nhận nil, nó tự động bỏ qua điều kiện đó và chain tiếp!
end
